def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            # check if key exists and expired
            if key in cache:
                _, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]

            if key in cache:
                # update existing, not expired
                cache[key] = [value, t]
                cache.move_to_end(key)
            else:
                # new entry (or was expired/removed)
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)

        elif kind == 'get':
            if key in cache:
                value, wt = cache[key]
                if t >= wt + ttl:
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)

    return results

